const TH16_RICE: int = 480;    // source etSprite type 8, color 4/13 (bullet-types.md)

const TIME_LIMIT: int = 2104;  // 120 shell buffer + 1980 source window + 4 startup slack
const OPENING_BUFFER: int = 120;

// ---- source 412 moveRand(60, 4, 1.0) + 504 moveLimit(0.0f, 128.0f, 280.0f, 96.0f) ----
// movement.md recipe: direction inner box = centre +- width/4 => x[-70,70], y[104,152];
// per-tick clamp = centre +- width/2 => x[-140,140], y[80,176].
// int slot 0: next step count; fx slot 0/1: logical unit vector.
sub arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 80fx { ny = 80fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub begin_move_rand(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    arm_next_step();
}

sub move_rand_step() {
    // Source 412b90: signed unit random * pi, kept as unwrapped BAM ints.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
        // Deliberately not normalised before the source fabs tests.
    }
    if $self_y < 104fx {
        if a < 0 { a = -a; }
    } else if $self_y > 152fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Source +/-pi/2 guard, epsilon 0.05 rad = 522 BAM.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    begin_move_rand(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_next_step();
    }
}

// ---- source 257-338 Boss2_at(var A, var B, var C) ----
// A: source et slot, B: color (type 8), C: per-wave ring rotation.
async sub boss2_at(color: int, dir: angle) {
    var rank: int = global(GVAR_RANK);
    var ways: int = 20;              // source 272: !E 10, !N/!H/!LO 20
    if rank == RANK_EASY { ways = 10; }
    var wave_gap: int = 14;          // source 325-333
    if rank == RANK_HARD { wave_gap = 10; }
    if rank == RANK_LUNATIC { wave_gap = 8; }
    var seg1: int = 60;              // source 278-285 STEP a
    var speed1: fx = 2fx;            // source 295 STEP s
    var seg2: int = 120;             // source 304-311 STEP a
    var speed2: fx = 1.5fx;          // source 313 STEP s
    if rank == RANK_HARD { seg1 = 30; speed1 = 3fx; speed2 = 2.5fx; }
    if rank == RANK_LUNATIC { seg1 = 30; speed1 = 6fx; seg2 = 40; speed2 = 2.8fx; }

    sh_reset(0);                     // source 260 etNew
    sh_sprite(0, TH16_RICE, color);  // source 262 etSprite(type 8, color)
    sh_aim(0, 0);                    // source 261 etAim(mode 3: fixed ring)
    sh_ring(0, 1);
    sh_count(0, ways, 1);            // source 272 etCount
    sh_speed(0, 1.5fx, 0fx);         // source 274 etSpeed(1.5,1.0), 1 layer -> 1.5
    sh_angle(0, 90deg, 0deg);        // source 273 etAngle(pi/2, 2deg); 1 layer -> spread inert
    // source 314 etDist(24) with 275-276 ANIM a=1 birth shift -4*1.5 = -6 => net 18
    sh_dist(0, 18fx);
    sh_xform(0, HOOK(seg1, speed1, seg2, speed2));

    var base: angle = 90deg;         // source 315 %D = pi/2
    for i in 0..12 {                 // source 316-336 $E = 12
        sh_angle(0, base, 0deg);     // source 319 etAngle(%D, 0)
        sh_fire(0);                  // source 324 etOn
        base = base + dir;           // source 320 %D += %C
        if rank >= RANK_HARD { base = base + dir; }  // source 321-322 !HL
        wait(wave_gap);              // source 334 wait
    }
}

// Source 275-313 EX chain, per bullet:
//   0x2 ANIM a=1 (birth shift folded into sh_dist; animation omitted)
//   0x800000 SAVE (angle restored at the second STEP boundary)
//   0x100 OFFSCREEN a=160 b=0
//   0x10 STEP a=seg1 b=1 c=0 d=0 r=+pi/2 s=speed1, linear decay to 0 then +90 deg turn
//   0x10 STEP a=seg2 b=1 c=3 d=2 r=9999999 (SAVE angle) s=speed2
// d=2 in the second STEP is documented as not yet verified (ex-effects.md); see report.
xformdef HOOK(seg1: int, speed1: fx, seg2: int, speed2: fx) {
    offscreen_keep(160);             // source OFFSCREEN a=160, b=0
    step_speed(0fx, seg1);           // decay current speed to 0 over seg1 ticks
    wait(seg1);
    turn(90deg);                     // c=0 at segment boundary: angle += r
    set_speed(speed1);               // restore target speed
    step_speed(0fx, seg2);
    wait(seg2);
    set_angle(at_spawn($self_angle)); // c=3: restore the SAVE angle
    set_speed(speed2);
}

// ---- real boss (source Boss state carried into this segment) ----
async sub boss_main() {
    set_invuln(65535);              // shared invulnerable shell
    set_hitbox(24fx);               // source Boss 501 setHitbox(48,48) -> r=24
    set_hurtbox(20fx);              // source Boss 500 setHurtbox(40,40) -> r=20
    // source 204-206: moveVel(0,0) + moveVelTime/movePosTime(0,...) clear inherited motion
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    var rank: int = global(GVAR_RANK);
    var first_gap: int = 80;        // source 227-234 wait([-1])
    if rank == RANK_HARD { first_gap = 50; }
    if rank == RANK_LUNATIC { first_gap = 10; }
    wait(60);                       // source 218 (animation waits kept, playback omitted)
    wait(60);                       // source 221
    loop {                          // source 224 -> Boss2_1144 / Boss2_1552
        spawn boss2_at(4, 1deg);    // source 226 Boss2_at(0, 4, +1deg) async
        card_wait(first_gap);
        move_rand_step();           // source 237 moveRand(60,4,1.0)
        card_wait(60);
        spawn boss2_at(13, -1deg);  // source 239 Boss2_at(1, 13, -1deg) async
        card_wait(first_gap);
        move_rand_step();           // source 250
        card_wait(60);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 14100, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
